draw(A--B--C--D--cycle);
draw((.75,0)--(0,1)--(1.5,.5)--cycle);
label("$A$", A, NW);
label("$B$", B, NE);
label("$C$", C, SE);
label("$D$", D, SW);
label("$N$", (0.75,0), S, red);
label("$M$", (1.5,.5), E, red);
