label("$B$", B, SW);
label("$C$", C, SE);
label("$I$", I, dir(90));
label("$M$", M, NW);
label("$N$", N, NE);
[/asy]

Therefore, the perimeter of triangle $AMN$ is simply \begin{align*}
AM + AN + MN &= AM + AN + MI + NI \\
&= AM + AN + MB + NC \\
&= (AM + MB) + (AN + NC) \\
&= AB + AC \\
&= 17 + 24 \\
&= \boxed{41}.
\end{align*}

